// Defensive normalizer for DePIN network status feeds (JSON or status-page
// HTML). The template points at the Grass status page — point it at any
// DePIN network (Gradient, Silencio, Helium, ...) by setting feedUrl.
const input = $input.first().json;
const body = input.body ?? input;
let raw = '';
if (typeof body === 'string') raw = body;
else if (body && typeof body === 'object') raw = JSON.stringify(body);

let components = [];
if (body && typeof body === 'object') {
  const cand = body.components ?? body.incidents ?? body.statuses ?? body.data;
  if (Array.isArray(cand)) components = cand;
  else if (Array.isArray(body)) components = body;
}

if (components.length === 0 && /(operational|degraded|outage|incident)/i.test(raw)) {
  // HTML status pages: extract status pill text + incident titles.
  const text = raw.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const m = text.match(/(All Systems Operational|Partial Outage|Major Outage|Minor[^.]{0,80})/i);
  components.push({ name: 'overall', status: m ? m[1] : 'unknown' });
}

const healthy = components.filter((c) => /operational|up|ok/i.test(String(c.status ?? ''))).length;

const rows = components.slice(0, 40).map((c) => ({
  name: c.name ?? c.title ?? 'unknown',
  status: c.status ?? c.state ?? 'unknown',
  detail: c.detail ?? c.description ?? ''
}));

return [{
  json: {
    userId: $json.userId ?? null,
    timestamp: new Date().toISOString(),
    network: $json.network ?? 'grass',
    healthy,
    total: components.length,
    components: rows
  }
}];

const raw = $json.choices && $json.choices[0] && $json.choices[0].message;
const analysis = raw && (raw.content || raw.text) || 'No AI analysis available.';
return [{
  json: { ...$json, analysis }
}];
